text:
Here's your water tracker: tap a glass to log it, and it counts up to your goal of 8.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: Segoe UI, sans-serif; text-align: center; margin: 24px; color: #1b3a4b; }
  h1 { font-size: 20px; margin-bottom: 4px; }
  #date { color: #6b8794; font-size: 13px; }
  #count { font-size: 40px; font-weight: 600; margin: 16px 0 4px; }
  #msg { height: 20px; font-size: 14px; color: #2a7f62; }
  #bar { height: 10px; background: #e3eef3; border-radius: 5px; overflow: hidden; margin: 12px auto; max-width: 320px; }
  #fill { height: 100%; width: 0; background: #3aa0d8; transition: width .3s; }
  #glasses { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; max-width: 360px; margin: 16px auto; }
  .g { width: 56px; height: 72px; border: 2px solid #3aa0d8; border-radius: 4px 4px 14px 14px; background: #fff; cursor: pointer; font-size: 22px; }
  .g.full { background: #3aa0d8; color: #fff; }
  button.c { font-size: 15px; padding: 8px 16px; margin: 4px; border: 1px solid #3aa0d8; background: #fff; color: #1b3a4b; border-radius: 6px; cursor: pointer; }
  button.c.main { background: #3aa0d8; color: #fff; }
</style>
</head>
<body>
  <h1>Water today</h1>
  <div id="date"></div>
  <div id="count">0 / 8</div>
  <div id="msg"></div>
  <div id="bar"><div id="fill"></div></div>
  <div id="glasses"></div>
  <button class="c main" id="add">+ Add a glass</button>
  <button class="c" id="sub">− Remove one</button>
  <button class="c" id="reset">Reset</button>
<script>
  var GOAL = 8;
  var today = new Date().toISOString().slice(0, 10);
  var n = 0;
  try {
    var s = JSON.parse(localStorage.getItem("water") || "{}");
    if (s.day === today) n = s.n || 0;
  } catch (e) {}

  function save() {
    try { localStorage.setItem("water", JSON.stringify({ day: today, n: n })); } catch (e) {}
  }

  function draw() {
    document.getElementById("date").textContent = new Date().toDateString();
    document.getElementById("count").textContent = n + " / " + GOAL;
    document.getElementById("fill").style.width = Math.min(100, n / GOAL * 100) + "%";
    document.getElementById("msg").textContent =
      n >= GOAL ? "Goal reached. Well done!" : (GOAL - n) + " more to go";
    var box = document.getElementById("glasses");
    box.innerHTML = "";
    for (var i = 0; i < GOAL; i++) {
      var b = document.createElement("button");
      b.className = "g" + (i < n ? " full" : "");
      b.textContent = i < n ? "💧" : "";
      (function (k) {
        b.onclick = function () { n = (n === k + 1) ? k : k + 1; save(); draw(); };
      })(i);
      box.appendChild(b);
    }
  }

  document.getElementById("add").onclick = function () { n++; save(); draw(); };
  document.getElementById("sub").onclick = function () { if (n > 0) n--; save(); draw(); };
  document.getElementById("reset").onclick = function () { n = 0; save(); draw(); };
  draw();
</script>
</body>
</html>
```

It starts fresh each day. Want a reminder to drink water at set times?
